def _arbol(nodos, x):
    i = 0
    while nodos[i][0] >= 0:
        f, t, izq, der, _ = nodos[i]
        i = izq if x[f] <= t else der
    return nodos[i][4]


def logit_riesgo(caso):
    """Logit de P(alucina) promediado sobre los modelos del conjunto."""
    c = extraer(caso)
    x = [c[n] for n in NOMBRES]
    raws = [base + sum(_arbol(a, x) for a in arboles) for base, arboles in MODELOS]
    return sum(raws) / len(raws)


class Guardian:
    def score(self, caso):
        if not MODELOS:
            raise RuntimeError("modelo vacío: ejecuta entrenar_guardian.py")
        z = logit_riesgo(caso) - math.log(CORTE / (1.0 - CORTE))
        return 1.0 / (1.0 + math.exp(-max(-30.0, min(30.0, z))))
